cat > tests/PaymentAuthorization.ArchitectureTest/LayerDependencyTests.cs <<'E'
using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private const string DomainNs = "PaymentAuthorization.Domain";
    private const string ApplicationNs = "PaymentAuthorization.Application";
    private const string InfrastructureNs = "PaymentAuthorization.Infrastructure";

    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(AuthorizePayment).Assembly;
    private static readonly Assembly Infrastructure = typeof(HttpPaymentGateway).Assembly;

    [Fact]
    public void Domain_depends_on_no_other_layer() =>
        AssertNoDependencies(Domain, ApplicationNs, InfrastructureNs);

    [Fact]
    public void Application_does_not_depend_on_infrastructure() =>
        AssertNoDependencies(Application, InfrastructureNs);

    [Theory]
    [InlineData("System.Net.Http")]
    [InlineData("System.IO")]
    [InlineData("System.Text.Json")]
    public void Domain_and_application_do_not_use_technical_namespaces(string technicalNamespace)
    {
        AssertNoDependencies(Domain, technicalNamespace);
        AssertNoDependencies(Application, technicalNamespace);
    }

    [Fact]
    public void Layer_assemblies_do_not_reference_outer_layers()
    {
        Assert.DoesNotContain(Domain.GetReferencedAssemblies(), a => a.Name!.StartsWith("PaymentAuthorization.") );
        Assert.DoesNotContain(Application.GetReferencedAssemblies(), a => a.Name == Infrastructure.GetName().Name);
    }

    private static void AssertNoDependencies(Assembly assembly, params string[] forbidden)
    {
        var result = Types.InAssembly(assembly).ShouldNot().HaveDependencyOnAny(forbidden).GetResult();
        Assert.True(result.IsSuccessful,
            $"{assembly.GetName().Name} must not depend on {string.Join(", ", forbidden)}. Offenders: {string.Join(", ", result.FailingTypeNames ?? [])}");
    }
}
